import openpyxl, os
in_x=os.environ['IN_XLSX']; out_x=os.environ['OUT_XLSX']
wi=openpyxl.load_workbook(in_x); wo=openpyxl.load_workbook(out_x)
si=wi['Sheet1']; so=wo['Sheet1']
for coord in ['L79','M79','E956','F956','J726','E724']:
    print(coord, repr(si[coord].value), '->', repr(so[coord].value))
# count diffs across whole sheet excluding AO
diff=0
for r in range(1,1289):
    for c in range(1,42):
        if c==41: continue
        a=si.cell(row=r,column=c).value; b=so.cell(row=r,column=c).value
        if a!=b:
            diff+=1
            if diff<=40: print('DIFF', si.cell(row=r,column=c).coordinate, repr(a), repr(b))
print('total non-AO diffs', diff)
